local shape_chunks = {}
for i = 1, 4 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "details" },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.DataStoreNotReady = errors.define({
  tag = "DataStoreNotReady",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { includes = "try again later" } } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.IdentityProviderNotConfigured = errors.define({
  tag = "IdentityProviderNotConfigured",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { includes = "IdP must be configured" } } },
  fields = { "details" },
})
classes.LlmAddOnRequired = errors.define({
  tag = "LlmAddOnRequired",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { includes = "Large Language Model add-on" } } },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})

local ops = {}
for i = 1, 2 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "gcp.discoveryengine_v1",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "gcp-api",
    prefix = "Discoveryengine",
    service = "discoveryengine",
    labels = "gcp",
    attributes = { ["gcp.client.service"] = "discoveryengine" },
    propagate = "w3c",
    response_headers = {
      { header = "x-request-id", name = "http.response.header.x-request-id", transform = "list" },
      { header = "request-id", name = "http.response.header.request-id", transform = "list" },
      {
        header = "x-goog-request-id",
        name = "http.response.header.x-goog-request-id",
        transform = "list",
      },
    },
  },
}
